import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.CVaJrGn7.js";const u=JSON.parse('{"title":"MCP server","description":"Author and validate GuideFlow tours from any MCP client — a read-only server holding no credentials and making no network calls.","frontmatter":{"description":"Author and validate GuideFlow tours from any MCP client — a read-only server holding no credentials and making no network calls.","keywords":"guideflow mcp server, model context protocol, agentic tour authoring, ai product tours, mcp tools","head":[["link",{"rel":"canonical","href":"https://realnerdzw.github.io/GuideFlow/guide/mcp"}],["meta",{"property":"og:url","content":"https://realnerdzw.github.io/GuideFlow/guide/mcp"}],["meta",{"property":"og:title","content":"MCP server — GuideFlow.js"}],["meta",{"property":"og:description","content":"Author and validate GuideFlow tours from any MCP client — a read-only server holding no credentials and making no network calls."}],["meta",{"name":"twitter:title","content":"MCP server — GuideFlow.js"}],["meta",{"name":"twitter:description","content":"Author and validate GuideFlow tours from any MCP client — a read-only server holding no credentials and making no network calls."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Guide\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/guide/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"Mcp\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/guide/mcp/\\"}]}"]]},"headers":[],"relativePath":"guide/mcp.md","filePath":"guide/mcp.md","lastUpdated":1786207781000}'),s={name:"guide/mcp.md"};function n(l,e,r,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="mcp-server" tabindex="-1">MCP server <a class="header-anchor" href="#mcp-server" aria-label="Permalink to &quot;MCP server&quot;">​</a></h1><p>Point an MCP client at a project and it can find, read, write and validate its product tours — using the same validator <code>guideflow validate</code> and the DevTools Recorder use.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @guideflow/mcp</span></span></code></pre></div><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;guideflow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;guideflow-mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--root&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/path/to/your/project&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="the-inversion" tabindex="-1">The inversion <a class="header-anchor" href="#the-inversion" aria-label="Permalink to &quot;The inversion&quot;">​</a></h2><p><code>@guideflow/ai</code> calls a model <strong>from the browser</strong>, which means the customer&#39;s API key is in the bundle. This is the other direction, and it is the more defensible half of the &quot;AI-powered&quot; claim:</p><blockquote><p>Expose the authoring engine as tools, and let whatever agent the operator already trusts do the generating.</p></blockquote><p>Two consequences follow, and both are the point:</p><ul><li><strong>No credentials, no network.</strong> This server calls nothing. There is nothing to leak. <code>guideflow_author_flow</code> does <strong>not</strong> call a model — the client <em>is</em> the model. It converts and validates what the model wrote.</li><li><strong>Every tool is read-only.</strong> Nothing writes a file. Authoring returns the exact bytes and lets the client&#39;s own file tools save them, under whatever permissions the operator already granted.</li></ul><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><h3 id="guideflow-list-flows" tabindex="-1"><code>guideflow_list_flows</code> <a class="header-anchor" href="#guideflow-list-flows" aria-label="Permalink to &quot;`guideflow_list_flows`&quot;">​</a></h3><p>Every <code>*.flow.json</code> under the root, with a health summary: whether it is valid, how many errors and warnings, how many steps, and its structural fingerprint. Paginated.</p><p>There is no hosted flow store — a flow is a <a href="/GuideFlow/guide/hosting-flows">static asset</a> — so this walks a directory. <code>node_modules</code>, <code>.git</code>, <code>dist</code>, <code>build</code>, <code>coverage</code> and dotted directories are skipped; the walk is bounded to 8 levels and 500 files.</p><p>An invalid flow is still <strong>named</strong>: the id is recovered from the raw JSON when validation withheld it, because &quot;which file is the broken tour?&quot; is exactly the question you ask when something is broken.</p><h3 id="guideflow-get-flow" tabindex="-1"><code>guideflow_get_flow</code> <a class="header-anchor" href="#guideflow-get-flow" aria-label="Permalink to &quot;`guideflow_get_flow`&quot;">​</a></h3><p>One flow, by <code>path</code> or by <code>flowId</code>, with the derived facts that are easy to get wrong by eye — <code>stepCount</code> walks the <code>NEXT</code> path from <code>initial</code> rather than summing every state&#39;s array, which is the distinction that once put a Done button on step one of a two-state tour. Two files declaring the same id is reported as ambiguous rather than silently resolved to the first.</p><h3 id="guideflow-validate-flow" tabindex="-1"><code>guideflow_validate_flow</code> <a class="header-anchor" href="#guideflow-validate-flow" aria-label="Permalink to &quot;`guideflow_validate_flow`&quot;">​</a></h3><p>The engine&#39;s real rules. Every issue carries a stable <code>code</code>, a <code>path</code>, and a <code>hint</code> naming the fix in one imperative sentence.</p><p>Selector rules are skipped, not failed: there is no DOM in this process.</p><h3 id="guideflow-author-flow" tabindex="-1"><code>guideflow_author_flow</code> <a class="header-anchor" href="#guideflow-author-flow" aria-label="Permalink to &quot;`guideflow_author_flow`&quot;">​</a></h3><p>A linear step list becomes a valid <code>FlowDefinition</code>: one state per step, the <code>NEXT</code> transitions between them, <code>final: true</code> on the last, and the envelope. Then it validates the result and refuses to hand back something the engine would mishandle.</p><p>It returns <code>fileContents</code> — save it yourself.</p><h2 id="why-there-is-no-simulate" tabindex="-1">Why there is no <code>simulate</code> <a class="header-anchor" href="#why-there-is-no-simulate" aria-label="Permalink to &quot;Why there is no `simulate`&quot;">​</a></h2><p>The original proposal had a fifth tool: drive a flow headlessly against a URL and return step-by-step screenshots. It is the most valuable of the five, and it is deliberately not here.</p><p>It needs a browser download, a running copy of your app, and a screenshot transport. This project has spent ten phases deleting things that were half of that, and <code>apps/e2e</code> is a standing measurement of what the full thing costs. Shipping a <code>simulate</code> that works on a static page and silently does nothing useful on a real SPA would be worse than not having one.</p><p>What exists instead: <code>guideflow_validate_flow</code> catches every <em>structural</em> failure with no browser at all — including the dangling transition that makes the engine truncate a tour <strong>and record it as completed</strong>, so it never shows again. Selector verification against a real page is the <a href="/GuideFlow/packages/devtools">DevTools Recorder</a>&#39;s job, where there is a real DOM.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><p>Every path goes through one sandbox function, and there is no way to opt out.</p><ul><li><strong>The root is the operator&#39;s choice, never a tool argument.</strong> A <code>root</code> parameter would let a model that had been talked into it point the server anywhere on the disk.</li><li><code>..</code> is collapsed and then refused.</li><li>Containment is checked on path <strong>segments</strong>. A naive prefix check accepts <code>/srv/tours-secret</code> for a root of <code>/srv/tours</code>; this does not.</li><li>Symlinks are resolved and re-checked — including for a file that <strong>does not exist yet</strong> underneath a directory symlink pointing out of the root, which a <code>try { realpath() } catch { accept }</code> would wave through.</li></ul><p>The server also writes nothing, so the worst a confused agent can do is read a flow file you pointed it at.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/GuideFlow/guide/authoring">Authoring</a> — the validator and the flow-file format</li><li><a href="/GuideFlow/guide/hosting-flows">Hosting flows</a> — why a flow is a file</li><li><a href="/GuideFlow/packages/devtools">@guideflow/devtools</a> — the Recorder, for selectors against a real page</li></ul>',32)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
